from pathlib import Path
from check_native_candidate_geometry import load
P=Path(__file__).resolve().parents[1];archive=P/'hardware/native/Calxus_RevA_final.epro2';D=load(archive)
a=json.loads((P/'validation/native-final-drc-readback-summary.json').read_text());paths=json.loads((P/'validation/native-final-usb-path-lengths.json').read_text());out=[]
for name in ['SIL','UART','UP','UP_B']:
 measurement=next(x for x in a['nativeNetLengths']if x['base']=='USB_'+('UP' if name=='UP_B' else name));sides={}
 for polarity in ['DP','DM']:
  key=f'{name}_{polarity}'+('_upstream'if name=='SIL'else'');p=paths['paths'][key];ts=[t for t in D['lines']if t['net']==p['net']];line_sum_mil=sum(math.hypot(t['x2']-t['x1'],t['y2']-t['y1'])for t in ts);live=measurement['positive'if polarity=='DP'else'negative'];assert abs(line_sum_mil-live)<.0001
  edge_sums=collections.defaultdict(float)
